// Where each league's figures were read: the rulebook, its edition, and the page it was read on. docs/sources.md has the rule for
// each figure. A rulebook's text is not copied; only its dimensions, which are facts.

/** A rulebook (or a page that publishes its figures). */
export interface LeagueSource {
  id: string;
  /** The document: "NCAA Men's and Women's Basketball Rules and Interpretations". */
  title: string;
  /** Who publishes it. */
  by: string;
  /** The edition: a season or a year. */
  edition: string;
  /** The address it was read at, on the date in `read`. */
  url: string;
  /** The date it was read (yyyy-mm-dd). */
  read: string;
  /** What was taken from it. */
  note?: string;
}

const source = (s: LeagueSource): [string, Readonly<LeagueSource>] => [s.id, Object.freeze(s)];

const READ = "2026-10-13";
const BUDO_READ = "2026-10-14";

